<template>
  <el-card class="history" data-testid="history-panel">
    <h3>{{ t('passportHistory.title') }}</h3>
    <el-alert v-if="health" :title="health.state === 'consistent' ? t('passportHistory.consistent') : t('passportHistory.needsReconciliation')" :type="health.state === 'consistent' ? 'success' : 'warning'" :closable="false" data-testid="history-health" />
    <p v-if="health" class="hash">{{ t('passportHistory.current') }} V{{ health.db_version ?? '—' }} · {{ t('passportHistory.fileVersion') }} V{{ health.file_version ?? '—' }} · {{ t('passportHistory.manifest') }} V{{ health.manifest_version ?? '—' }} · {{ health.classification }}<br>{{ health.file_hash }}</p>
    <el-button :disabled="busy" data-testid="history-refresh" @click="refresh">{{ t('common.refresh') }}</el-button>
    <span v-if="health && health.state !== 'consistent'"><el-button v-permisaction="['passport:publish:execute']" :disabled="busy" data-testid="history-reconcile" @click="openRecovery">{{ t('passportPublish.reconcile') }}</el-button></span>
    <ProTable :table="table" :card="false" :paginated="false" row-key="revision.id" data-testid="version-history">
      <el-table-column type="expand"><template #default="{ row }"><dl v-if="row.revision"><dt>{{ t('passportReview.hash') }}</dt><dd>{{ row.revision.source_content_hash }}</dd><dt>{{ t('passportHistory.source') }}</dt><dd>{{ row.revision.source_review_record_id }}</dd><dt>{{ t('passportPublish.hash') }}</dt><dd>{{ row.revision.payload_hash }}</dd><dt>{{ t('passportHistory.release') }}</dt><dd>{{ row.revision.release_identifier }}</dd><dt>{{ t('passportHistory.record') }}</dt><dd>{{ row.record.id }}</dd><dt>{{ t('passportPublish.publisher') }}</dt><dd>{{ row.revision.published_by }}</dd><dt>{{ t('passportPublish.state') }}</dt><dd>{{ row.record.publish_status }}</dd></dl></template></el-table-column>
      <el-table-column :label="t('passportPublish.version')" min-width="70"><template #default="{ row }">V{{ row.revision?.version_number }}</template></el-table-column>
      <el-table-column :label="t('passportHistory.kind')" min-width="120"><template #default="{ row }">{{ row.version_type ? t(`passportHistory.${row.version_type}`) : '—' }} <el-tag v-if="row.current">{{ t('passportHistory.current') }}</el-tag><span v-if="row.revision?.rollback_source_revision_id">{{ t('passportHistory.rollbackFrom') }} V{{ sourceVersion(row.revision.rollback_source_revision_id) }}</span></template></el-table-column>
      <el-table-column :label="t('passportPublish.publishedAt')" min-width="100"><template #default="{ row }"><DateCell :value="row.revision?.published_at" /></template></el-table-column>
      <el-table-column :label="t('passportPublish.assets')" min-width="70"><template #default="{ row }">{{ row.record?.asset_count }}</template></el-table-column>
      <template #actions="{ row }"><el-button link type="primary" :data-testid="`version-detail-${row.revision?.version_number}`" @click="show(row)">{{ t('passportHistory.detail') }}</el-button><span v-if="health?.state === 'consistent' && workflow === 'published'"><el-button v-permisaction="['passport:history:rollback']" link type="warning" :disabled="busy" :data-testid="`rollback-${row.revision?.version_number}`" @click="openRollback(row)">{{ t('passportHistory.rollback') }}</el-button></span></template>
    </ProTable>
    <h4>{{ t('passportHistory.compare') }}</h4>
    <div class="actions"><el-select v-model="left" :aria-label="t('passportHistory.left')" data-testid="compare-left"><el-option v-for="v in history?.versions ?? []" :key="v.revision.id" :value="v.revision.id" :label="`V${v.revision.version_number}`" /></el-select><el-select v-model="right" :aria-label="t('passportHistory.right')" data-testid="compare-right"><el-option v-for="v in history?.versions ?? []" :key="v.revision.id" :value="v.revision.id" :label="`V${v.revision.version_number}`" /></el-select><el-button :disabled="!left || !right || busy" data-testid="compare-run" @click="compare">{{ t('passportHistory.compare') }}</el-button></div>
    <div v-if="diff" data-testid="version-diff"><el-collapse><el-collapse-item v-for="d in diff.differences" :key="d.group + d.path" :title="`${label(d.group)} · ${d.path} · ${label(d.change)}`"><div class="comparison"><pre>{{ pretty(d.before) }}</pre><pre>{{ pretty(d.after) }}</pre></div></el-collapse-item></el-collapse></div>
    <el-tabs v-if="history">
      <el-tab-pane :label="t('passportHistory.attempts')"><el-table :data="history.attempts" data-testid="attempt-history"><el-table-column :label="t('passportPublish.version')" min-width="70"><template #default="{ row }">V{{ row.revision?.version_number }}</template></el-table-column><el-table-column :label="t('passportPublish.state')" min-width="120"><template #default="{ row }">{{ row.record?.publish_status }}</template></el-table-column><el-table-column :label="t('passportHistory.reason')" min-width="150"><template #default="{ row }">{{ row.record?.rollback_reason ?? row.record?.error_message }}</template></el-table-column><el-table-column :label="t('passportHistory.detail')" min-width="100"><template #default="{ row }"><el-button link @click="auditDetail = row">{{ t('passportHistory.detail') }}</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane :label="t('passportReview.history')"><el-table :data="history.reviews"><el-table-column prop="attempt_number" :label="t('passportReview.attempt')" min-width="60" /><el-table-column prop="decision" :label="t('passportReview.decision')" min-width="100" /><el-table-column prop="submitted_by" :label="t('passportReview.submitter')" min-width="70" /><el-table-column prop="reviewed_by" :label="t('passportReview.reviewer')" min-width="70" /><el-table-column prop="comment" :label="t('passportReview.comment')" min-width="130" /><el-table-column prop="rejection_reason" :label="t('passportReview.reason')" min-width="130" /></el-table></el-tab-pane>
      <el-tab-pane :label="t('passportHistory.audit')"><el-select v-model="category" :aria-label="t('passportHistory.category')" @change="refresh"><el-option :label="t('passportHistory.all')" value="" /><el-option v-for="c in categories" :key="c" :label="label(c)" :value="c" /></el-select><el-timeline data-testid="audit-timeline"><el-timeline-item v-for="a in history.audit" :key="a.id" :timestamp="a.created_at"><el-button link @click="auditDetail = a">{{ label(a.category) }} · {{ a.event_type }} · {{ a.actor_user_id }}</el-button></el-timeline-item></el-timeline></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="detailOpen" :title="t('passportHistory.detail')" width="min(900px, 94vw)"><div v-if="detail" data-testid="version-detail"><p>{{ t('passportPublish.version') }} V{{ detail.version.revision.version_number }} · {{ label(detail.version.version_type) }}</p><p class="hash">{{ t('passportPublish.hash') }}: {{ detail.version.revision.payload_hash }}</p><el-tag data-testid="version-integrity" :type="detail.integrity.state === 'verified' ? 'success' : 'danger'">{{ label(detail.integrity.state) }}</el-tag><el-button data-testid="version-verify" :disabled="busy" @click="verify">{{ t('passportHistory.verify') }}</el-button><el-collapse><el-collapse-item :title="t('passportHistory.source')"><pre>{{ pretty(detail.version) }}</pre></el-collapse-item><el-collapse-item :title="t('passportHistory.payload')"><pre>{{ pretty(detail.payload) }}</pre></el-collapse-item><el-collapse-item :title="t('passportHistory.manifest')"><pre>{{ pretty(detail.manifest) }}</pre></el-collapse-item><el-collapse-item :title="t('passportPublish.assets')"><div v-for="a in detail.assets" :key="a.id" class="hash">{{ a.asset_key }} · {{ a.asset_role }} · {{ a.published_filename }} · {{ a.file_size }} bytes<br>{{ a.sha256 }}<p>{{ t('passportHistory.references') }}: {{ a.reference_count }}</p></div></el-collapse-item><el-collapse-item :title="t('passportHistory.audit')"><pre>{{ pretty(detail.audit) }}</pre></el-collapse-item></el-collapse></div></el-dialog>
    <el-dialog v-model="confirmOpen" :title="recovering ? t('passportPublish.reconcile') : t('passportHistory.rollback')" width="min(580px, 94vw)" :close-on-click-modal="false" :show-close="!busy"><p>{{ recovering ? t('passportHistory.recoveryNotice') : t('passportHistory.rollbackNotice', { version: target?.revision.version_number, current: health?.db_version }) }}</p><el-input v-model="reason" type="textarea" maxlength="1000" show-word-limit :aria-label="t('passportHistory.reason')" data-testid="history-reason" /><el-button type="primary" :loading="busy" :disabled="!reason.trim() || /[<>]/.test(reason)" data-testid="history-confirm" @click="execute">{{ t('common.dialogConfirm') }}</el-button></el-dialog>
    <el-dialog :model-value="auditDetail !== null" :title="t('passportHistory.detail')" width="min(800px, 94vw)" @close="auditDetail = null"><pre>{{ pretty(auditDetail) }}</pre></el-dialog>
  </el-card>
</template>
<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import ProTable from '@/components/ProTable/index.vue'
import DateCell from '@/components/DateCell/index.vue'
import { useTable } from '@/composables/useTable'
import { getHistory, getHealth, getVersion, verifyVersion, compareVersions, rollbackVersion } from '@/api/passport/history'
import type { VersionHistory, VersionSummary, VersionDetail, CurrentHealth, VersionDiff } from '@/api/passport/history'
import { reconcile } from '@/api/passport/publication'
const props = defineProps<{ batchId: string; workflow: string }>(); const emit = defineEmits<{ saved: []; health: [value: CurrentHealth] }>()
const { t, te } = useI18n(); const history = ref<VersionHistory>(); const health = ref<CurrentHealth>(); const busy = ref(false)
const detail = ref<VersionDetail>(); const detailOpen = ref(false); const auditDetail = ref<unknown>(null); const diff = ref<VersionDiff>(); const left = ref(''); const right = ref(''); const category = ref('')
const categories = ['Product', 'Batch', 'Review', 'Publish', 'Rollback', 'Asset', 'SystemRecovery']; const target = ref<VersionSummary>(); const reason = ref(''); const key = ref(''); const recovering = ref(false); const confirmOpen = ref(false)
const table = useTable<VersionSummary>({ api: async() => ({ code: 200, msg: '', data: history.value?.versions ?? [] }), paginated: false, immediate: false })
const pretty = (v: unknown) => JSON.stringify(v, null, 2); const label = (v: string) => te(`passportHistory.${v}`) ? t(`passportHistory.${v}`) : v
const sourceVersion = (id: string) => history.value?.versions.find(v => v.revision.id === id)?.revision.version_number ?? '—'
async function refresh() { try { history.value = (await getHistory(props.batchId, category.value)).data; health.value = (await getHealth(props.batchId)).data; emit('health', health.value); await table.getList(); if (!left.value) left.value = history.value.versions.at(-1)?.revision.id ?? ''; if (!right.value) right.value = history.value.versions[0]?.revision.id ?? '' } catch { /* request reports errors */ } }
watch(() => [props.batchId, props.workflow], () => { left.value = ''; right.value = ''; void refresh() }, { immediate: true })
async function show(v: VersionSummary) { if (!v.revision) return; try { detail.value = (await getVersion(props.batchId, v.revision.id)).data; detailOpen.value = true } catch { /* shared request error */ } }
async function verify() { if (!detail.value) return; busy.value = true; try { detail.value.integrity = (await verifyVersion(props.batchId, detail.value.version.revision.id)).data } catch { /* shared error */ } finally { busy.value = false } }
async function compare() { try { diff.value = (await compareVersions(props.batchId, left.value, right.value)).data } catch { /* shared error */ } }
function openRollback(v: VersionSummary) { if (busy.value) return; target.value = v; reason.value = ''; key.value = crypto.randomUUID(); recovering.value = false; confirmOpen.value = true }
function openRecovery() { reason.value = ''; recovering.value = true; confirmOpen.value = true }
async function execute() { if (busy.value || !reason.value.trim()) return; busy.value = true; try { if (recovering.value) await reconcile(props.batchId, reason.value); else if (target.value) await rollbackVersion(props.batchId, { target_revision_id: target.value.revision.id, expected_current_revision_id: health.value?.db_current_id ?? null, idempotency_key: key.value, rollback_reason: reason.value }); confirmOpen.value = false } catch { /* retain key for safe retry */ } finally { await refresh(); busy.value = false; emit('saved') } }
</script>
<style scoped>
.history { margin:18px 0;overflow-wrap:anywhere; }pre { white-space:pre-wrap;overflow-wrap:anywhere;max-height:480px;overflow:auto; }.hash { font-family:monospace; }.actions { display:flex;gap:10px;margin:12px 0;flex-wrap:wrap; }.actions .el-select { max-width:180px; }.comparison { display:grid;grid-template-columns:1fr 1fr;gap:12px; }.comparison pre { min-width:0; }.el-timeline { margin-top:18px; }
</style>
